{"file_path":"/Users/gkhoo-c/.Projects/mxc-c0/work/eval-c0-wordstat-20261030T043030Z/wordstat/core.py","content":""""Pure core logic for wordstat."""
from __future__ import annotations

import json
import re
from collections import Counter


def analyze(text: str, top: int) -> dict:
    words = re.findall(r"[a-z0-9]+", text.lower())
    ranked = sorted(Counter(words).items(), key=lambda kv: (-kv[1], kv[0]))[:top]
    return {
        "lines": len(text.splitlines()),
        "words": len(words),
        "chars": len(text),
        "top": [{"word": w, "count": c} for w, c in ranked],
    }


def format_text(result: dict) -> str:
    top = "".join(" %s=%d" % (t["word"], t["count"]) for t in result["top"])
    return "lines: %d\nwords: %d\nchars: %d\ntop:%s\n" % (
        result["lines"],
        result["words"],
        result["chars"],
        top,
    )


def format_json(result: dict) -> str:
    return json.dumps(result) + "\n"
"}

